Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final currencyItems = [
      CurrencyModel(
        id: '1',
        nominal: 1,
        name: 'Доллар США',
        symbol: 'USD',
        value: 78.4181,
        previousValue: 78.5,
      ),
    ];

    final newsItems = [
      NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
    ];

    Widget dashboardWidget() => buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        );

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => newsItems);
    });

    testWidgets('should show progress indicator while loading and data afterwards', (WidgetTester tester) async {
      await tester.pumpWidget(dashboardWidget());

      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      await tester.pumpAndSettle();

      expect(find.byType(CircularProgressIndicator), findsNothing);
      expect(find.text('USD'), findsOneWidget);
      expect(find.text('Заголовок 1'), findsOneWidget);
    });

    testWidgets('should request fresh rates and fresh news feed on open', (WidgetTester tester) async {
      await tester.pumpWidget(dashboardWidget());
      await tester.pumpAndSettle();

      verify(mockCurrencyRepository.fetchRates(argThat(isA<CurrencyPageRequest>().having((r) => r.base, 'base', 'USD')))).called(1);
      verify(mockNewsRepository.loadNewsFeed(argThat(isA<NewsFeedFilter>().having((f) => f.forceRefresh, 'forceRefresh', isTrue)))).called(1);
    });
  });
}
